test:
	@echo "=== Test: opencode-serve --help passthrough ==="
	docker compose run --rm opencode-serve --help 2>&1 | head -5
	@echo ""
	@echo "=== Test: opencode-web --help passthrough ==="
	docker compose run --rm opencode-web --help 2>&1 | head -5
	@echo ""
	@echo "=== Test: generic-worker env validation (no REPO_URL) ==="
	docker compose run --rm opencode-generic-worker 2>&1 | grep -q "REPO_URL"
