	@echo ""
	@echo "=== Test: generic-worker repo_inspect ==="
	GH_TOKEN=$$(gh auth token 2>/dev/null || echo "dummy") \
		docker compose run --rm \
		-e REPO_URL=https://github.com/tbrandenburg/pyrag.git \
		-e ISSUE=99 \
		opencode-generic-worker \
		sh -c 'git log --oneline -5 && find . -type f -not -path "./.git/*" | wc -l && head -5 README.md'
	@echo ""
	@echo "All tests passed."

